int config_ok = 1;
int star_usable = 0, triad_usable = 0;
adcs_quat_t star_q = {1, 0, 0, 0}, triad_q = {1, 0, 0, 0};
adcs_quat_t selected_q, prev_q, blended_q, scaled_prev, scaled_sel, sum_q;
double disagreement = 0.0;
double w_star = 0.0, w_triad = 0.0;
double star_res, triad_res;

if (rs_config.enable != 0 && rs_config.enable != 1) config_ok = 0;
if (!isfinite(rs_config.max_residual_rad) || rs_config.max_residual_rad < 0.0) config_ok = 0;
if (!isfinite(rs_config.fuse_angle_rad) || rs_config.fuse_angle_rad < 0.0) config_ok = 0;
if (!isfinite(rs_config.switch_margin_rad) || rs_config.switch_margin_rad < 0.0) config_ok = 0;
if (!isfinite(rs_config.residual_weight_floor_rad) || rs_config.residual_weight_floor_rad <= 0.0) config_ok = 0;
if (!isfinite(rs_config.output_alpha) || rs_config.output_alpha <= 0.0 || rs_config.output_alpha > 1.0) config_ok = 0;
if (rs_config.switch_confirm_cycles < 1U || rs_config.switch_confirm_cycles > 20U) config_ok = 0;
if (rs_config.max_outage_cycles < 1U || rs_config.max_outage_cycles > 20U) config_ok = 0;
if (!isfinite(rs_config.fuse_angle_rad) || rs_config.fuse_angle_rad > ADCS_PI) config_ok = 0;

if (!config_ok) {
    rs_state.primary = RS_FAULT;
    rs_state.candidate = RS_NONE;
    rs_state.candidate_good = 0U;
    rs_state.outage = 0U;
    rs_state.previous_q_bi = (adcs_quat_t){1, 0, 0, 0};
}

if (rs_state.primary == RS_FAULT || !config_ok) {
    rs_output.source = RS_FAULT;
    rs_output.primary = RS_FAULT;
    rs_output.candidate = RS_NONE;
    rs_output.candidate_good = 0U;
    rs_output.outage = rs_state.outage;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    rs_state.primary = RS_FAULT;
    rs_state.candidate = RS_NONE;
    rs_state.previous_q_bi = (adcs_quat_t){1, 0, 0, 0};
    rs_state.candidate_good = 0U;
    return;
}

if (rs_config.enable == 0) {
    rs_state.primary = RS_NONE;
    rs_state.candidate = RS_NONE;
    rs_state.candidate_good = 0U;
    rs_state.outage = 0U;
    rs_state.previous_q_bi = (adcs_quat_t){1, 0, 0, 0};
    rs_output.source = RS_NONE;
    rs_output.primary = RS_NONE;
    rs_output.candidate = RS_NONE;
    rs_output.candidate_good = 0U;
    rs_output.outage = 0U;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}

star_res = rs_input.star_residual_rad;
triad_res = rs_input.triad_residual_rad;

if (rs_input.star_q_bi != NULL && isfinite(star_res) && star_res >= 0.0 &&
    star_res <= rs_config.max_residual_rad &&
    adcs_quat_normalize(rs_input.star_q_bi, &star_q) == ADCS_OK)
    star_usable = 1;

if (rs_input.triad_q_bi != NULL && isfinite(triad_res) && triad_res >= 0.0 &&
    triad_res <= rs_config.max_residual_rad &&
    adcs_quat_normalize(rs_input.triad_q_bi, &triad_q) == ADCS_OK)
    triad_usable = 1;

if (rs_state.primary != RS_STAR && rs_state.primary != RS_TRIAD) {
    if (star_usable) rs_state.primary = RS_STAR;
    else if (triad_usable) rs_state.primary = RS_TRIAD;
    else rs_state.primary = RS_NONE;
    rs_state.candidate = RS_NONE;
    rs_state.candidate_good = 0U;
}

if (rs_state.primary == RS_STAR && !star_usable) {
    if (triad_usable) {
        rs_state.primary = RS_TRIAD;
        rs_state.candidate = RS_NONE;
        rs_state.candidate_good = 0U;
    } else {
        rs_state.primary = RS_NONE;
    }
} else if (rs_state.primary == RS_TRIAD && !triad_usable) {
    if (star_usable) {
        rs_state.primary = RS_STAR;
        rs_state.candidate = RS_NONE;
        rs_state.candidate_good = 0U;
    } else {
        rs_state.primary = RS_NONE;
    }
}

if (star_usable && triad_usable && (rs_state.primary == RS_STAR || rs_state.primary == RS_TRIAD)) {
    rs_source_t alt = (rs_state.primary == RS_STAR) ? RS_TRIAD : RS_STAR;
    double prim_res = (rs_state.primary == RS_STAR) ? star_res : triad_res;
    double alt_res = (alt == RS_STAR) ? star_res : triad_res;
    rs_state.candidate = alt;
    if (alt_res + rs_config.switch_margin_rad <= prim_res) {
        if (rs_state.candidate_good < 0xFFFFFFFFU) rs_state.candidate_good++;
        if (rs_state.candidate_good >= rs_config.switch_confirm_cycles) {
            rs_state.primary = alt;
            rs_state.candidate = RS_NONE;
            rs_state.candidate_good = 0U;
        }
    } else {
        rs_state.candidate_good = 0U;
    }
} else {
    rs_state.candidate = RS_NONE;
    rs_state.candidate_good = 0U;
}

if (star_usable && triad_usable) {
    double dot = adcs_quat_abs_dot(&star_q, &triad_q);
    if (dot > 1.0) dot = 1.0;
    if (dot < -1.0) dot = -1.0;
    disagreement = 2.0 * acos(dot);
} else {
    disagreement = 0.0;
}

if (star_usable && triad_usable && disagreement <= rs_config.fuse_angle_rad) {
    adcs_quat_t triad_aligned = triad_q;
    double dot = star_q.w * triad_q.w + star_q.x * triad_q.x + star_q.y * triad_q.y + star_q.z * triad_q.z;
    if (dot < 0.0) {
        triad_aligned.w = -triad_aligned.w;
        triad_aligned.x = -triad_aligned.x;
        triad_aligned.y = -triad_aligned.y;
        triad_aligned.z = -triad_aligned.z;
    }
    w_star = 1.0 / (rs_config.residual_weight_floor_rad + star_res);
    w_triad = 1.0 / (rs_config.residual_weight_floor_rad + triad_res);
    sum_q.w = w_star * star_q.w + w_triad * triad_aligned.w;
    sum_q.x = w_star * star_q.x + w_triad * triad_aligned.x;
    sum_q.y = w_star * star_q.y + w_triad * triad_aligned.y;
    sum_q.z = w_star * star_q.z + w_triad * triad_aligned.z;
    if (adcs_quat_normalize(&sum_q, &selected_q) != ADCS_OK)
        selected_q = star_q;
    rs_output.source = RS_FUSED;
} else if (rs_state.primary == RS_STAR && star_usable) {
    selected_q = star_q;
    w_star = 1.0 / (rs_config.residual_weight_floor_rad + star_res);
    w_triad = 0.0;
    rs_output.source = RS_STAR;
} else if (rs_state.primary == RS_TRIAD && triad_usable) {
    selected_q = triad_q;
    w_star = 0.0;
    w_triad = 1.0 / (rs_config.residual_weight_floor_rad + triad_res);
    rs_output.source = RS_TRIAD;
} else if (star_usable) {
    selected_q = star_q;
    w_star = 1.0 / (rs_config.residual_weight_floor_rad + star_res);
    w_triad = 0.0;
    rs_output.source = RS_STAR;
    rs_state.primary = RS_STAR;
} else if (triad_usable) {
    selected_q = triad_q;
    w_star = 0.0;
    w_triad = 1.0 / (rs_config.residual_weight_floor_rad + triad_res);
    rs_output.source = RS_TRIAD;
    rs_state.primary = RS_TRIAD;
} else {
    rs_state.outage++;
    if (rs_state.outage >= rs_config.max_outage_cycles) {
        rs_state.primary = RS_FAULT;
        rs_output.source = RS_FAULT;
    } else {
        rs_output.source = RS_NONE;
    }
    rs_output.primary = rs_state.primary;
    rs_output.candidate = RS_NONE;
    rs_output.candidate_good = 0U;
    rs_output.outage = rs_state.outage;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}

prev_q = rs_state.previous_q_bi;
{
    double dotp = prev_q.w * selected_q.w + prev_q.x * selected_q.x + prev_q.y * selected_q.y + prev_q.z * selected_q.z;
    if (dotp < 0.0) {
        selected_q.w = -selected_q.w;
        selected_q.x = -selected_q.x;
        selected_q.y = -selected_q.y;
        selected_q.z = -selected_q.z;
    }
}
scaled_prev.w = (1.0 - rs_config.output_alpha) * prev_q.w;
scaled_prev.x = (1.0 - rs_config.output_alpha) * prev_q.x;
scaled_prev.y = (1.0 - rs_config.output_alpha) * prev_q.y;
scaled_prev.z = (1.0 - rs_config.output_alpha) * prev_q.z;
scaled_sel.w = rs_config.output_alpha * selected_q.w;
scaled_sel.x = rs_config.output_alpha * selected_q.x;
scaled_sel.y = rs_config.output_alpha * selected_q.y;
scaled_sel.z = rs_config.output_alpha * selected_q.z;
sum_q.w = scaled_prev.w + scaled_sel.w;
sum_q.x = scaled_prev.x + scaled_sel.x;
sum_q.y = scaled_prev.y + scaled_sel.y;
sum_q.z = scaled_prev.z + scaled_sel.z;
if (adcs_quat_normalize(&sum_q, &blended_q) != ADCS_OK)
    blended_q = (adcs_quat_t){1, 0, 0, 0};
rs_state.previous_q_bi = blended_q;

rs_output.primary = rs_state.primary;
rs_output.candidate = rs_state.candidate;
rs_output.candidate_good = rs_state.candidate_good;
rs_output.outage = rs_state.outage;
rs_output.disagreement_rad = disagreement;
rs_output.star_weight = w_star;
rs_output.triad_weight = w_triad;
rs_output.q_bi = blended_q;

