    (!isfinite(rs_config.output_alpha)) || (rs_config.output_alpha <= 0.0) ||
    (rs_config.output_alpha > 1.0) ||
    (rs_config.switch_confirm_cycles < 1U) || (rs_config.switch_confirm_cycles > 20U) ||
    (rs_config.max_outage_cycles < 1U) || (rs_config.max_outage_cycles > 20U) ||
