    d = star_q.w * triad_q.w + star_q.x * triad_q.x + star_q.y * triad_q.y + star_q.z * triad_q.z;
    if (d < 0.0) {
        triad_aligned = (adcs_quat_t){-triad_q.w, -triad_q.x, -triad_q.y, -triad_q.z};
    } else {
        triad_aligned = triad_q;
    }
    ws = 1.0 / (rs_config.residual_weight_floor_rad + star_res);
    wt = 1.0 / (rs_config.residual_weight_floor_rad + triad_res);
    sum = ws + wt;
    selected = (adcs_quat_t){
        (ws * star_q.w + wt * triad_aligned.w) / sum,
        (ws * star_q.x + wt * triad_aligned.x) / sum,
        (ws * star_q.y + wt * triad_aligned.y) / sum,
        (ws * star_q.z + wt * triad_aligned.z) / sum
