        rs_output.source = RS_TRIAD;
    } else if (star_ok) {
        selected_q = star_q;
        rs_output.source = RS_STAR;
    } else {
        selected_q = triad_q;
        rs_output.source = RS_TRIAD;
    }
}

/* 9. sign-align to previous, blend, normalize */
{
    double dot_prev = selected_q.w * rs_state.previous_q_bi.w +
                      selected_q.x * rs_state.previous_q_bi.x +
                      selected_q.y * rs_state.previous_q_bi.y +
                      selected_q.z * rs_state.previous_q_bi.z;
    if (dot_prev < 0.0) {
        selected_q.w = -selected_q.w;
        selected_q.x = -selected_q.x;
        selected_q.y = -selected_q.y;
        selected_q.z = -selected_q.z;
    }
    aligned_q = selected_q;
    blended_q.w = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.w +
                  rs_config.output_alpha * aligned_q.w;
    blended_q.x = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.x +
                  rs_config.output_alpha * aligned_q.x;
    blended_q.y = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.y +
                  rs_config.output_alpha * aligned_q.y;
    blended_q.z = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.z +
                  rs_config.output_alpha * aligned_q.z;
    (void)adcs_quat_normalize(&blended_q, &blended_q);
}

rs_output.primary = rs_state.primary;
rs_output.candidate = rs_state.candidate;
rs_output.candidate_good = rs_state.candidate_good;
rs_output.outage = rs_state.outage;
rs_output.q_bi = blended_q;
rs_state.previous_q_bi = blended_q;
